138	impl LinuxCommon {
139	    pub fn new(
140	        signal: LoopSignal,
141	    ) -> (
142	        Self,
143	        PriorityQueueCalloopReceiver<RunnableVariant>,
144	        calloop::channel::Channel<()>,
145	    ) {
146	        let (main_sender, main_receiver) = PriorityQueueCalloopReceiver::new();
147	        let (wake_sender, wake_receiver) = calloop::channel::channel();
148	
149	        #[cfg(any(feature = "wayland", feature = "x11"))]
150	        let text_system = Arc::new(crate::linux::CosmicTextSystem::new("IBM Plex Sans"));
151	        #[cfg(not(any(feature = "wayland", feature = "x11")))]
152	        let text_system = Arc::new(gpui::NoopTextSystem::new());
153	
154	        let callbacks = PlatformHandlers::default();
155	
156	        let dispatcher = Arc::new(LinuxDispatcher::new(main_sender));
157	
158	        let background_executor = BackgroundExecutor::new(dispatcher.clone());
159	
160	        let common = LinuxCommon {
161	            background_executor,
162	            foreground_executor: ForegroundExecutor::new(dispatcher),
163	            text_system,
164	            appearance: WindowAppearance::Light,
165	            auto_hide_scrollbars: false,
166	            button_layout: WindowButtonLayout::linux_default(),
167	            callbacks,
168	            signal,
169	            menus: Vec::new(),
170	            app_name: None,
171	            system_notifications: crate::linux::system_notifications::SystemNotificationState::new(
172	            ),
173	            wake_sender,
174	            wake_listener_started: false,
175	        };
176	
177	        (common, main_receiver, wake_receiver)
178	    }
