180	    pub(crate) fn start_wake_listener(&mut self) {
181	        if !self.wake_listener_started {
182	            #[cfg(all(target_os = "linux", any(feature = "wayland", feature = "x11")))]
183	            smol::spawn({
184	                let wake_sender = self.wake_sender.clone();
185	                async move {
186	                    if let Err(error) = listen_for_system_wake(wake_sender).await {
187	                        log::debug!("failed to listen for system wake events: {error:?}");
188	                    }
189	                }
190	            })
191	            .detach();
192	
193	            self.wake_listener_started = true;
194	        }
195	    }
196	
197	    pub(crate) fn handle_system_wake(&mut self) {
198	        if let Some(mut callback) = self.callbacks.system_wake.take() {
199	            callback();
200	            self.callbacks.system_wake = Some(callback);
201	        }
202	    }
203	}
