268	        on_finish_launching();
269	
270	        LinuxClient::run(&self.inner);
271	
272	        let quit = self
273	            .inner
274	            .with_common(|common| common.callbacks.quit.take());
275	        if let Some(mut fun) = quit {
276	            fun();
277	        }
278	    }
