755	pub(super) fn open_uri_internal(
756	    executor: BackgroundExecutor,
757	    uri: &str,
758	    activation_token: Option<String>,
759	) {
760	    if let Some(uri) = ashpd::Uri::parse(uri).log_err() {
761	        executor
762	            .spawn(async move {
763	                let mut xdg_open_failed = false;
764	                for mut command in open::commands(uri.to_string()) {
765	                    if let Some(token) = activation_token.as_ref() {
766	                        command.env("XDG_ACTIVATION_TOKEN", token);
767	                    }
768	                    let program = format!("{:?}", command.get_program());
769	                    match smol::process::Command::from(command).spawn() {
770	                        Ok(mut cmd) => match cmd.status().await {
771	                            Ok(status) if status.success() => return,
772	                            Ok(status) => {
773	                                log::error!("Command {} exited with status: {}", program, status);
774	                                xdg_open_failed = true;
775	                            }
776	                            Err(e) => {
777	                                log::error!("Failed to get status from {}: {}", program, e);
778	                                xdg_open_failed = true;
779	                            }
780	                        },
781	                        Err(e) => {
782	                            log::error!("Failed to open with {}: {}", program, e);
783	                            xdg_open_failed = true;
784	                        }
785	                    }
786	                }
787	
788	                if xdg_open_failed {
789	                    match ashpd::desktop::open_uri::OpenFileRequest::default()
790	                        .activation_token(activation_token.map(ashpd::ActivationToken::from))
791	                        .send_uri(&uri)
