1221	/// Resolve a Linux `dev_t` to PCI vendor/device IDs via sysfs, returning a
1222	/// [`CompositorGpuHint`] that the GPU adapter selection code can use to
1223	/// prioritize the compositor's rendering device.
1224	#[cfg(any(feature = "wayland", feature = "x11"))]
1225	pub(super) fn compositor_gpu_hint_from_dev_t(dev: u64) -> Option<gpui_wgpu::CompositorGpuHint> {
1226	    fn dev_major(dev: u64) -> u32 {
1227	        ((dev >> 8) & 0xfff) as u32 | (((dev >> 32) & !0xfff) as u32)
1228	    }
1229	
1230	    fn dev_minor(dev: u64) -> u32 {
1231	        (dev & 0xff) as u32 | (((dev >> 12) & !0xff) as u32)
1232	    }
1233	
1234	    fn read_sysfs_hex_id(path: &str) -> Option<u32> {
1235	        let content = std::fs::read_to_string(path).ok()?;
1236	        let trimmed = content.trim().strip_prefix("0x").unwrap_or(content.trim());
1237	        u32::from_str_radix(trimmed, 16).ok()
1238	    }
1239	
1240	    let major = dev_major(dev);
1241	    let minor = dev_minor(dev);
1242	
1243	    let vendor_path = format!("/sys/dev/char/{major}:{minor}/device/vendor");
1244	    let device_path = format!("/sys/dev/char/{major}:{minor}/device/device");
1245	
1246	    let vendor_id = read_sysfs_hex_id(&vendor_path)?;
1247	    let device_id = read_sysfs_hex_id(&device_path)?;
1248	
1249	    log::info!(
1250	        "Compositor GPU hint: vendor={:#06x}, device={:#06x} (from dev {major}:{minor})",
1251	        vendor_id,
1252	        device_id,
1253	    );
1254	
1255	    Some(gpui_wgpu::CompositorGpuHint {
1256	        vendor_id,
1257	        device_id,
1258	    })
1259	}
